"""Tier-3 adaptive fallback (PLAN.md §6): "off-script turns generated by an
LLM caller at temperature 0, TTS'd and degraded at runtime with that
session's fixed noise bed and seed." Generated at call time, never
pre-rendered, since by definition this content isn't known in advance.

Gemini call verified live before building this: gemini-2.5-flash is already
retired (the API's own 404 names gemini-3.8-flash as the replacement), and
temperature:0 alone still spends ~500 "thinking" tokens by default -
thinkingConfig:{"thinkingBudget":0} cut a real call from 547 total tokens
and several seconds to 57 tokens and ~1.8s.

Scoped limitation, not hidden: the noise mixed in here is a FRESH clip at
the session's condition parameters (same noise type/SNR/codec), not
sample-continuous with the Phase 4 session's one pre-rendered bed - this
module doesn't track the live call's exact elapsed offset into that
recording. Flagged as a follow-up in the Phase 6 plan.
"""
from __future__ import annotations

import json
import os
import urllib.error
import urllib.request

import numpy as np

from vqlab.audio import Audio, db_to_lin, rms_dbfs, write_wav
from vqlab.fx import codec as K
from vqlab.fx import noise as NZ

GEMINI_MODEL = "gemini-3.8-flash"
GEMINI_URL = f"https://generativelanguage.googleapis.com/v1beta/models/{GEMINI_MODEL}:generateContent"

GENERIC_FALLBACK: dict[str, str] = {
    "en-US": "Sorry, could you say that again?",
    "en-SG": "Sorry ah, can you say again?",
    "hi-IN": "माफ़ कीजिये, क्या आप फिर से बता सकते हैं?",
    "es-ES": "Perdone, ¿puede repetir eso?",
    "id-ID": "Maaf, bisa diulang lagi?",
}


def generate_reply_text(agent_utterance: str, lang: str, remaining_fields: list[str],
                        remaining_field_values: dict[str, str] | None = None,
                        best_guess_intent: str | None = None, best_guess_confidence: float = 0.0,
                        timeout_s: float = 6.0) -> tuple[str, str]:
    """Returns (reply_text, divergence_reason). "no_llm_configured" when
    GEMINI_API_KEY is unset - the call must keep going on the generic
    fallback, never fail (CLAUDE.md: never a hard fail).

    remaining_field_values: {field_name: the scenario's own canonical
    scripted sentence for that field} (CallerState.remaining_field_values)
    - MUST be supplied whenever available. Confirmed live this is a real
    bug otherwise: telling Gemini only the field NAME ("date") with no
    reference at all, it fabricated "Friday, the 24th" when the scenario's
    real scripted date was October 15th - a vendor then correctly heard
    and read back exactly that WRONG date, which looked like a vendor
    failure in the score but was entirely ours. The caller is supposed to
    be a deterministic, scripted state machine with every fact already
    known (CLAUDE.md) - the LLM here exists only to phrase an off-script
    turn naturally, never to invent a fact that has a known correct
    answer.

    best_guess_intent/confidence: tier 3 fires on LOW confidence, not NO
    information - Laya's point guess is still real signal (e.g. "closing"
    at 0.58 on a garbled transcript is usually right, just not confident
    enough to act on blindly). Dropping it left Gemini generating an
    on-topic-but-wrong reply (more date talk) to what was actually the
    agent's closing line, garbled by espeak+whisper into something tier 1/2
    couldn't resolve confidently."""
    key = os.environ.get("GEMINI_API_KEY")
    if not key:
        return GENERIC_FALLBACK.get(lang, GENERIC_FALLBACK["en-US"]), "no_llm_configured"

    remaining_field_values = remaining_field_values or {}
    if remaining_fields:
        details = "; ".join(
            f'{f} (reference - what you would say if asked: "{remaining_field_values[f]}")'
            if f in remaining_field_values else f
            for f in remaining_fields
        )
        needs_line = (f"You still need to provide: {details}. If your reply mentions any of "
                      "these, the FACTS must exactly match their reference sentence (the same "
                      "name/number/date) - never invent, guess, or substitute a different one, "
                      "even if a different one seems more natural to say.")
    else:
        needs_line = "You have already provided everything you need to - don't volunteer anything new."
    hint = ""
    if best_guess_intent and best_guess_confidence > 0:
        hint = (f" (A rough, not-fully-confident guess is that the agent is doing "
               f"'{best_guess_intent}' - weight this but verify it fits the actual words.)")
    prompt = (
        f"You are a caller on a phone booking call, speaking {lang}. "
        f"{needs_line} "
        f'The agent just said: "{agent_utterance}".{hint} '
        "Reply with ONE short, natural spoken sentence a real caller would say next. "
        "No quotation marks, no explanation, just the sentence."
    )
    body = json.dumps({
        "contents": [{"parts": [{"text": prompt}]}],
        "generationConfig": {"temperature": 0, "thinkingConfig": {"thinkingBudget": 0}},
    }).encode()
    req = urllib.request.Request(
        f"{GEMINI_URL}?key={key}", data=body,
        headers={"Content-Type": "application/json"}, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=timeout_s) as r:
            data = json.loads(r.read())
        text = data["candidates"][0]["content"]["parts"][0]["text"].strip()
        if not text:
            raise ValueError("empty Gemini response")
        return text, "llm_generated"
    except (urllib.error.URLError, TimeoutError, OSError, json.JSONDecodeError,
           KeyError, IndexError, ValueError) as e:
        # A plain read-timeout (slow/overloaded Gemini) raises bare
        # TimeoutError/OSError here, not urllib.error.URLError - verified
        # live: this escaped uncaught mid-call, skipped the caller's
        # explicit PJSIP cleanup, and the process segfaulted (exit 139)
        # instead of the call just continuing on the generic fallback like
        # every other failure mode here already does.
        return GENERIC_FALLBACK.get(lang, GENERIC_FALLBACK["en-US"]), f"llm_error:{type(e).__name__}"


# ElevenLabs' default model (eleven_multilingual_v2) measured at 3.19s for a
# short adaptive reply - real enough to make a live vendor re-prompt mid-
# generation. eleven_flash_v2_5, verified live, does the same text in 0.39s -
# barely slower than espeak's 0.07s, but as the real configured voice rather
# than a robotic fallback. Previously this path forced espeak unconditionally
# for speed; verified live that trade cost real clarity - a vendor's own ASR
# mis-transcribed an espeak reply ("Wait, I haven't given you the date yet."
# heard back as "Wade. I haven't given you the name yet."), which can cause
# more confusion/turns than the latency it saved. Flash gets both.
ADAPTIVE_ELEVENLABS_MODEL = "eleven_flash_v2_5"


def synth_and_degrade(text: str, lang: str, lang_meta: dict, tts: str,
                      condition: dict, out_path: str, scratch_dir: str,
                      work_sr: int = 16000) -> str:
    raw_path = os.path.join(scratch_dir, "_adaptive_raw.wav")
    if tts == "espeak":
        from vqlab.corpus import tts_espeak
        a = tts_espeak(text, lang_meta["tts_voice"], raw_path)
    else:
        from vqlab.corpus import tts_elevenlabs
        a = tts_elevenlabs(text, lang_meta["elevenlabs_voice_id"], raw_path,
                           model=ADAPTIVE_ELEVENLABS_MODEL)
    a = a.resample(work_sr)

    nz_name = condition.get("noise")
    snr = condition.get("snr_db")
    if nz_name:
        rng = np.random.default_rng()  # fresh - see module docstring
        nz = NZ.make_noise(nz_name, len(a.samples), work_sr, rng, **(condition.get("noise_params") or {}))
        if snr is not None:
            nz = nz * db_to_lin(rms_dbfs(a.samples) - float(snr) - rms_dbfs(nz))
        else:
            nz = nz * db_to_lin(-42.0 - rms_dbfs(nz))
        a = Audio(a.samples + nz, work_sr)

    cname = condition.get("codec", "g711u")
    a = K.roundtrip(a, cname, return_sr=int(condition.get("codec_sr", 8000)))
    write_wav(out_path, a)
    return out_path
